// Тикет #6a86f7fc «שיעורי תורה». Опора: «שיעורי תורה» AC1–AC3; реджект 27.09, ответ 28.09; Figma 454:8682.
// ВНИМАНИЕ (из плана): тестовый урок «שיעור בדיקה — לא תוכן מאושר» удалят перед релизом — тогда тест переписать.
import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, tapLabel, expectVisibleText, expectTextContains } from '../../helpers/ui.ts';
import { goTab, TABS } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const LESSON = 'שיעור בדיקה — לא תוכן מאושר';

describe('שיעורי תורה', () => {
  afterEach(async () => { await toHome(); });

  it('TL-01 Список уроков и урок с текстом и источником #6a86f7fc @prod-safe', async () => {
    // 1. «תפילות» → «שיעורי תורה».
    await goTab('תפילות');
    await tapLabel('שיעורי תורה, השיעורים הזמינים לקריאה');

    // 2. Список: заголовок, пояснение о порядке, урок с «מקור:».
    await (await byText('שיעורי תורה')).waitForDisplayed({ timeout: 20000 });
    await expectTextContains('השיעורים מוצגים לפי סדר האלף־בית של שמם');
    await expectVisibleText(LESSON);
    await expectTextContains('מקור:');

    // 3. Открыть урок: заголовок, текст (2 абзаца), источник, нижняя навигация; без аудио/видео.
    await (await byText(LESSON)).click();
    await expectTextContains('מקור: שיעור בדיקה לצורכי QA — אינו תוכן מאושר');
    await expectVisibleText(LESSON);
    for (const tab of TABS) await expectVisibleText(tab);
    // Аудио/видео: в нативном дереве нет плеера (Android VideoView / iOS «Play»-кнопки «השמע»).
    await expect(byText('השמע')).not.toBeDisplayed();
    if (driver.isAndroid) {
      const players = await driver.$$('android=new UiSelector().className("android.widget.VideoView")').getElements();
      expect(players.length).toBe(0);
    }
  });
});
